Review and correct this Flatpak C code according to project type conventions. The callback signature is part of an existing public API and must not change. Return only corrected code in solution.c.

typedef void (*FlatpakProgressCallback) (guint progress, gpointer user_data);

static void
report_steps (GPtrArray *steps, FlatpakProgressCallback callback, gpointer user_data)
{
  for (guint i = 0; i < steps->len; i++)
    callback (i, user_data);
}

Review and correct this new internal Mutter C helper according to project type conventions. It is not part of a public API. Return only corrected code in solution.c, including any required standard headers.

static gint32
count_ascii_digits (const gchar *text, gsize text_len)
{
  gint32 count = 0;

  for (gsize i = 0; i < text_len; i++)
    if (text[i] >= '0' && text[i] <= '9')
      count++;

  return count;
}
